<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {IconArrowLeft,IconCheck,IconEye,IconHistory,IconPlus,IconX} from '@tabler/icons-vue'
import type {WikiApi,WikiTreeView,WikiRevisionView,Reference} from './api'
import {useWikiEditor} from './editor'
import MarkdownContent from './MarkdownContent'
import {useWikiLeaveGuard} from './navigation'
const props=defineProps<{api:WikiApi;uid:string|null;section:string;tree:WikiTreeView;admin:boolean;ru:boolean}>()
const emit=defineEmits<{saved:[];close:[]}>()
const editor=useWikiEditor(props.api)
const {document:doc,uid,kind,mainKind,mainUid,dirty,saving,error,forbidden,archived}=editor
const preview=ref(false),textarea=ref<HTMLTextAreaElement|null>(null),history=ref<WikiRevisionView[]>([]),old=ref<WikiRevisionView|null>(null),historyOpen=ref(false),historyOffset=ref(0),historyError=ref(false)
const references=ref<Record<string,Reference[]>>({}),refError=ref(false),filter=ref('')
const writable=computed(()=>props.admin&&!forbidden.value&&!saving.value)
const canSave=computed(()=>writable.value&&!!doc.value.section_uid&&(kind.value==='article'||!!mainUid.value))
const leaveGuard=useWikiLeaveGuard(()=>dirty.value,()=>saving.value)
const leaveDialog=ref<HTMLDialogElement|null>(null)
watch(leaveGuard.open,open=>{if(open)leaveDialog.value?.showModal();else leaveDialog.value?.close()})
const confirmLeave=()=>leaveGuard.canLeave()
defineExpose({canLeave:confirmLeave})
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload))
onUnmounted(()=>{window.removeEventListener('beforeunload',beforeUnload);leaveGuard.decide(false)})
async function close(){if(await confirmLeave())emit('close')}
async function save(publish=false){if(await (publish?editor.publish():editor.save()))emit('saved')}
async function archive(){if(!(await confirmLeave()))return;if(await editor.archive(!archived.value))emit('saved')}
async function reload(){if(await confirmLeave())await editor.reload()}
async function loadHistory(offset=0){historyError.value=false;try{history.value=await props.api.history(uid.value,offset);historyOffset.value=offset;historyOpen.value=true;old.value=null}catch{historyError.value=true}}
function insert(before:string,after=''){const field=textarea.value;if(!field)return;const start=field.selectionStart,end=field.selectionEnd;doc.value.body=doc.value.body.slice(0,start)+before+doc.value.body.slice(start,end)+after+doc.value.body.slice(end);field.focus()}
function addSource(){if((doc.value.sources??[]).length<20)(doc.value.sources??=[]).push({name:'',url:''})}
function matching(kind:string){return (references.value[kind]??[]).filter(r=>r.name.toLocaleLowerCase().includes(filter.value.toLocaleLowerCase()))}
watch(()=>props.uid,async value=>{if(value)await editor.load(value);else editor.initialize(props.section||props.tree.sections.find(s=>!s.parent_uid&&s.sort_order===3)?.uid||props.tree.sections[0]?.uid||'')},{immediate:true})
onMounted(async()=>{try{const entries=await Promise.all(['practices','poses','devices'].map(async k=>[k,await props.api.references(k)] as const));references.value=Object.fromEntries(entries)}catch{refError.value=true}})
</script>
<template>
 <section class="wiki-editor" :aria-label="ru?'Редактор Wiki':'Wiki editor'">
  <header class="wiki-editor-heading"><button class="wiki-text-link" :disabled="saving" @click="close"><IconArrowLeft :size="18"/>{{ru?'К библиотеке':'Back to library'}}</button><span class="muted">{{dirty?(ru?'Есть изменения':'Unsaved changes'):(ru?'Сохранено':'Saved')}}</span></header>
  <h2>{{uid?(ru?'Редактирование материала':'Edit page'):(ru?'Новая страница':'New page')}}</h2>
  <p v-if="!admin||forbidden" role="alert">{{ru?'Права редактирования недоступны. Введённый текст сохранён в этом окне.':'Editing access is unavailable. Your text remains in this window.'}}</p>
  <p v-if="error" role="alert">{{error==='VERSION_CONFLICT'?(ru?'Материал изменён в другом окне. Ваш текст сохранён здесь.':'The page changed in another window. Your text is kept here.'):(ru?'Не удалось сохранить. Проверьте поля, соединение и права.':'Could not save. Check fields, connection and access.')}} <button v-if="uid&&error==='VERSION_CONFLICT'" @click="reload">{{ru?'Загрузить свежую версию':'Load current version'}}</button></p>
  <form @submit.prevent="save()"><fieldset :disabled="!writable" class="wiki-editor-fields"><div v-if="!uid" class="wiki-form-row"><label>{{ru?'Вид материала':'Page type'}}<select v-model="kind"><option value="article">{{ru?'Статья':'Article'}}</option><option value="encyclopedia">{{ru?'Энциклопедия':'Encyclopedia'}}</option></select></label><template v-if="kind==='encyclopedia'"><label>{{ru?'Справочник':'Catalogue'}}<select v-model="mainKind" @change="mainUid=''"><option value="practices">{{ru?'Практики':'Practices'}}</option><option value="poses">{{ru?'Позы':'Poses'}}</option><option value="devices">{{ru?'Девайсы':'Devices'}}</option></select></label><label>{{ru?'Основной объект':'Main reference'}}<select v-model="mainUid" required><option value="" disabled>{{ru?'Выберите запись':'Choose entry'}}</option><option v-for="r in references[mainKind]??[]" :key="r.uid" :value="r.uid">{{r.name}}</option></select></label></template></div>
   <label>{{ru?'Название':'Title'}}<input v-model="doc.title" maxlength="160" :placeholder="ru?'Название материала':'Page title'"></label><div class="wiki-form-row"><label>{{ru?'Раздел':'Section'}}<select v-model="doc.section_uid" required><option v-for="s in tree.sections" :key="s.uid" :value="s.uid">{{s.title}}</option></select></label><label>{{ru?'Краткое описание':'Summary'}}<textarea v-model="doc.summary" maxlength="600" rows="2"/></label></div>
   <div class="wiki-format-toolbar" :aria-label="ru?'Форматирование':'Formatting'"><button type="button" @click="insert('**','**')"><strong>B</strong></button><button type="button" @click="insert('*','*')"><em>I</em></button><button type="button" @click="insert('\n## ')">H2</button><button type="button" @click="insert('\n- ')">• {{ru?'Список':'List'}}</button><button type="button" @click="insert('[','](https://)')">{{ru?'Ссылка':'Link'}}</button><button type="button" :aria-pressed="preview" @click="preview=!preview"><IconEye :size="17"/>{{ru?'Предпросмотр':'Preview'}}</button></div>
   <MarkdownContent v-if="preview" :source="doc.body"/><label v-else>{{ru?'Текст · Markdown':'Body · Markdown'}}<textarea ref="textarea" v-model="doc.body" class="wiki-body-editor" maxlength="100000" rows="15" spellcheck="true"/></label>
   <details class="wiki-related"><summary>{{ru?'Связанные записи справочников':'Related references'}}</summary><p v-if="refError" role="alert">{{ru?'Не удалось загрузить справочники.':'Could not load references.'}}</p><input v-model="filter" type="search" :aria-label="ru?'Найти связанную запись':'Find reference'" :placeholder="ru?'Поиск по справочникам':'Search references'"><div class="wiki-reference-pickers"><fieldset v-for="k in ['practices','poses','devices'] as const" :key="k"><legend>{{k==='practices'?(ru?'Практики':'Practices'):k==='poses'?(ru?'Позы':'Poses'):(ru?'Девайсы':'Devices')}}</legend><label v-for="r in matching(k)" :key="r.uid"><input v-model="doc[k==='practices'?'practice_uids':k==='poses'?'pose_uids':'device_uids']" type="checkbox" :value="r.uid">{{r.name}}</label></fieldset></div></details>
   <details class="wiki-related"><summary>{{ru?'Источники и миниатюра':'Sources and thumbnail'}}</summary><label>{{ru?'Локальная миниатюра':'Local thumbnail'}}<input :value="doc.thumbnail??''" maxlength="500" placeholder="/references/…webp" @input="doc.thumbnail=($event.target as HTMLInputElement).value||null"></label><div v-for="(s,i) in doc.sources??[]" :key="i" class="wiki-source-row"><input v-model="s.name" maxlength="160" :aria-label="ru?'Название источника':'Source name'" :placeholder="ru?'Название':'Name'"><input v-model="s.url" type="url" required maxlength="2000" :aria-label="ru?'URL источника':'Source URL'" placeholder="https://"><button type="button" class="icon-button" :aria-label="ru?'Удалить источник':'Remove source'" @click="doc.sources?.splice(i,1)"><IconX :size="18"/></button></div><button type="button" :disabled="(doc.sources?.length??0)>=20" @click="addSource"><IconPlus :size="16"/>{{ru?'Источник':'Source'}}</button></details>
  </fieldset><footer class="wiki-editor-actions"><button type="submit" :disabled="!canSave"><IconCheck :size="18"/>{{ru?'Сохранить черновик':'Save draft'}}</button><button type="button" :disabled="!canSave||!doc.title.trim()||!doc.body?.trim()||archived" @click="save(true)">{{ru?'Опубликовать':'Publish'}}</button><button v-if="uid" type="button" :disabled="!writable" @click="archive">{{archived?(ru?'Восстановить':'Restore'):(ru?'В архив':'Archive')}}</button><button v-if="uid" type="button" :disabled="saving" @click="loadHistory()"><IconHistory :size="17"/>{{ru?'История':'History'}}</button></footer></form>
  <section v-if="historyOpen" class="wiki-history"><h3>{{ru?'История редакций':'Revision history'}}</h3><button v-for="r in history" :key="r.uid" class="wiki-text-link" @click="old=r">{{new Date(r.created_at).toLocaleString(ru?'ru-RU':'en-GB')}} · {{r.document.title}}</button><div class="wiki-pagination"><button :disabled="historyOffset===0" @click="loadHistory(Math.max(0,historyOffset-50))">{{ru?'Назад':'Previous'}}</button><button :disabled="history.length<50" @click="loadHistory(historyOffset+50)">{{ru?'Далее':'Next'}}</button></div><article v-if="old"><h3>{{old.document.title}}</h3><MarkdownContent :source="old.document.body"/></article></section><p v-if="historyError" role="alert">{{ru?'Не удалось загрузить историю.':'Could not load history.'}}</p>
  <dialog ref="leaveDialog" class="wiki-leave-dialog" :aria-label="ru?'Несохранённые изменения':'Unsaved changes'" @cancel.prevent="leaveGuard.decide(false)"><h3>{{ru?'Несохранённые изменения':'Unsaved changes'}}</h3><p>{{ru?'Уйти без сохранения? Введённый текст будет потерян.':'Leave without saving? Your changes will be discarded.'}}</p><div class="wiki-editor-actions"><button type="button" autofocus @click="leaveGuard.decide(false)">{{ru?'Остаться':'Stay'}}</button><button type="button" @click="leaveGuard.decide(true)">{{ru?'Уйти без сохранения':'Discard and leave'}}</button></div></dialog>
 </section>
</template>
